/**
 * Context & Proxy factory — builds the typed `ctx` object passed to each
 * fluent action method.
 *
 * At the TypeScript level, ctx.trigger.vendorName is Ref<string>.
 * At runtime, a Proxy intercepts the property access and returns a Ref
 * with the correct RefData ({ kind: "trigger", name: "vendorName" }).
 *
 * This bridges compile-time type safety with runtime reference building.
 */
import type { CalculationTypeOfValue, Ref, Simplify, ToRefs } from "./ref.js";
/**
 * Deep ref — a `Ref<T>` that also exposes `T`'s string-keyed properties as
 * nested deep refs. This is what makes `ctx.actions.x.record.id` and
 * `ctx.trigger.record.summary` type-check: each property access yields
 * another `Ref` whose runtime proxy extends the dotted path in `RefData.name`.
 *
 * Arrays stop the recursion — you can't drill into an array element by type.
 */
export type DeepRef<T> = Ref<T, CalculationTypeOfValue<T>> & (T extends ReadonlyArray<unknown> ? unknown : T extends string | number | boolean | bigint | null | undefined ? unknown : T extends object ? {
    [K in keyof T & string]: DeepRef<T[K]>;
} : unknown);
/**
 * Maps each key of `T` to a `DeepRef` — used for both trigger outputs and
 * action outputs so that property drilling (`ctx.trigger.record.summary`,
 * `ctx.actions.x.record.id`) type-checks uniformly.
 */
export type DeepRefs<T> = {
    [K in keyof T]: DeepRef<T[K]>;
};
/**
 * Default open-ended shape for variables when the builder hasn't tracked
 * any typed `setVariable` calls yet — the generic-path form, where a variable
 * an action may create several variables: `ctx.variables.<action>.<varName>` is
 * `Ref<unknown>`.
 */
export type VariableRefs = {
    [actionName: string]: {
        [varName: string]: Ref<unknown>;
    };
};
/**
 * Narrow variable refs from fluent `setVariable` tracking (action name →
 * the variable's TS value type). A fluent variable action holds exactly one
 * variable named after the action, so the action-name access is the ref:
 * `ctx.variables.<name>` is `Ref<T>` — no second hop.
 */
type TypedVariableRefs<TVariables extends Record<string, unknown>> = {
    [ActionName in keyof TVariables]: Ref<TVariables[ActionName]>;
};
export type Context<TTrigger, TActions extends Record<string, unknown>, TVariables extends Record<string, unknown> = Record<string, never>> = {
    readonly trigger: DeepRefs<TTrigger>;
    readonly actions: Simplify<{
        [K in keyof TActions]: DeepRefs<TActions[K]>;
    }>;
    readonly variables: keyof TVariables extends never ? VariableRefs : TypedVariableRefs<TVariables> & VariableRefs;
};
/**
 * Creates a proxy that intercepts property access and returns trigger Refs.
 * Top-level access returns a deep ref so nested field drilling works:
 *   ctx.trigger.vendorName  → Ref { kind: "trigger", name: "vendorName" }
 *   ctx.trigger.record.id   → Ref { kind: "trigger", name: "record.id" }
 */
export declare function createTriggerProxy<T>(): DeepRefs<T>;
/**
 * Creates a proxy for a single action's outputs.
 * ctx.actions.findVendor.records → Ref with
 * { kind: "task", actionRefKey: "findVendor", name: "records" }
 */
export declare function createActionOutputProxy<T>(actionRefKey: string): DeepRefs<T>;
/**
 * Creates a proxy for the actions namespace.
 * ctx.actions → Proxy where each property access returns an action output proxy.
 */
export declare function createActionsProxy<TActions extends Record<string, unknown>>(actionNames: string[]): Context<never, TActions>["actions"];
/**
 * A forEach item that is both a Ref to the whole item and a proxy
 * with typed field access: item.fieldName → Ref<T[fieldName]>.
 */
export type ForEachItem<T> = Ref<T> & ToRefs<T>;
/**
 * Creates a forEach item proxy.
 * item.fieldName → Ref with { kind: "forEach", forEachActionName, name: "fieldName" }
 * Accessing the item directly (without a property) returns a Ref to the whole item.
 */
export declare function createForEachItemProxy<T>(forEachActionName: string): ForEachItem<T>;
/**
 * Build a complete Context object for a given point in the chain.
 *
 * `TVariables` is a phantom — it only affects the compile-time shape of
 * `ctx.variables`. The runtime proxy is still an open-ended lookup.
 */
export declare function buildContext<TTrigger, TActions extends Record<string, unknown>, TVariables extends Record<string, unknown> = Record<string, never>>(actionNames: string[]): Context<TTrigger, TActions, TVariables>;
export {};
